import { afterEach, describe, expect, it, vi } from 'vitest';

vi.mock('../render/live-window', () => ({
  inTurn: <T>(request: () => Promise<T>): Promise<T> => request(),
}));

/*
 * Program capture's real reader loop, with only its browser media/DOM/port APIs stood in for. All frames contain
 * generated bytes. Nothing requests this computer's screen, camera or microphone. A stopped track's processor
 * can finish later: its deferred WebStream completion must not clear the capture that replaced it at a new size.
 */

class GeneratedFrame {
  readonly format = 'RGBA';
  readonly visibleRect: { x: number; y: number; width: number; height: number };
  private closed = false;

  constructor(
    readonly codedWidth: number,
    readonly codedHeight: number,
    private readonly byte: number,
  ) {
    this.visibleRect = { x: 0, y: 0, width: codedWidth, height: codedHeight };
  }

  allocationSize(): number {
    return this.codedWidth * this.codedHeight * 4;
  }

  copyTo(destination: ArrayBuffer): Promise<PlaneLayout[]> {
    if (this.closed) throw new Error('A closed generated frame cannot be copied.');
    new Uint8Array(destination).fill(this.byte);
    return Promise.resolve([]);
  }

  clone(): VideoFrame {
    if (this.closed) throw new Error('A closed generated frame cannot be cloned.');
    return new GeneratedFrame(this.codedWidth, this.codedHeight, this.byte).asVideoFrame();
  }

  close(): void {
    this.closed = true;
  }

  asVideoFrame(): VideoFrame {
    return this as unknown as VideoFrame;
  }
}

class GeneratedTrack extends EventTarget {
  readyState: MediaStreamTrackState = 'live';
  readonly readable: ReadableStream<VideoFrame>;
  private controller: ReadableStreamDefaultController<VideoFrame> | null = null;
  private readerFinished = false;
  processorStarted = false;
  // MediaStreamTrack.stop() does not synchronously finish every pending processor read or fire 'ended'.
  readonly stop = vi.fn(() => {
    this.readyState = 'ended';
  });

  constructor(
    readonly width: number,
    readonly height: number,
  ) {
    super();
    this.readable = new ReadableStream<VideoFrame>({
      start: (controller) => {
        this.controller = controller;
      },
    });
  }

  getSettings(): MediaTrackSettings {
    return { width: this.width, height: this.height, frameRate: 30 };
  }

  frame(byte: number): void {
    this.enqueue(new GeneratedFrame(this.width, this.height, byte).asVideoFrame());
  }

  enqueue(frame: VideoFrame): void {
    if (!this.controller || this.readerFinished) throw new Error('No generated frame reader.');
    this.controller.enqueue(frame);
  }

  finishReader(): void {
    if (this.readerFinished) return;
    this.readerFinished = true;
    this.controller?.close();
  }

  endNaturally(): void {
    this.readyState = 'ended';
    this.dispatchEvent(new Event('ended'));
    this.finishReader();
  }

  asTrack(): MediaStreamTrack {
    return this as unknown as MediaStreamTrack;
  }
}

class EncoderPort {
  readonly messages: unknown[] = [];
  readonly start = vi.fn();
  readonly close = vi.fn();

  postMessage(message: unknown): void {
    this.messages.push(message);
  }
}

function videoBytes(port: EncoderPort): number[][] {
  return port.messages.flatMap((message) => {
    if (
      typeof message !== 'object' ||
      message === null ||
      !('kind' in message) ||
      message.kind !== 'video' ||
      !('data' in message) ||
      !(message.data instanceof ArrayBuffer)
    )
      return [];
    return [Array.from(new Uint8Array(message.data))];
  });
}

let disposeCapture: (() => Promise<void>) | null = null;

afterEach(async () => {
  try {
    await disposeCapture?.();
  } finally {
    disposeCapture = null;
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
    vi.resetModules();
  }
});

/** Video out is off (x30: absent before). */
const stopVideoOut = (capture: unknown) => {
  (capture as { stopVideoOut?: () => void }).stopVideoOut?.();
};

/** The page's show on screen (Session 58: the encoder takes the page's frames from then; absent before). */
const showOnScreen = (capture: unknown) => {
  (capture as { showOnScreen?: () => void }).showOnScreen?.();
};

/** `onScreen`: the page's show already on screen as capture starts (as when the stream's page has long been up). */
async function platform(tracks: GeneratedTrack[], { onScreen = true }: { onScreen?: boolean } = {}) {
  vi.resetModules();
  const lines: string[] = [];
  vi.spyOn(console, 'info').mockImplementation((message: unknown) => {
    if (typeof message === 'string') lines.push(message);
  });
  const page = new EventTarget();
  const body = { dataset: {} as Record<string, string> };
  interface Corner {
    id: string;
    dataset: Record<string, string>;
    style: { cssText: string; background: string };
    setAttribute: (name: string, value: string) => void;
  }
  const corners = new Map<string, Corner>();
  const document = {
    body: {
      ...body,
      appendChild: (corner: Corner) => {
        corners.set(corner.id, corner);
        return corner;
      },
    },
    getElementById: (id: string) => corners.get(id) ?? null,
    createElement: () => ({
      id: '',
      dataset: {},
      style: { cssText: '', background: '' },
      setAttribute: vi.fn(),
    }),
  };
  const queued = [...tracks];
  const getDisplayMedia = vi.fn(() => {
    const track = queued.shift();
    if (!track) return Promise.reject(new Error('Unexpected extra generated capture request.'));
    return Promise.resolve({ getVideoTracks: () => [track.asTrack()] } as unknown as MediaStream);
  });
  class Processor {
    readonly readable: ReadableStream<VideoFrame>;

    constructor({ track }: { track: MediaStreamTrack }) {
      const generated = tracks.find((candidate) => candidate.asTrack() === track);
      if (!generated) throw new Error('The processor received a non-generated track.');
      generated.processorStarted = true;
      this.readable = generated.readable;
    }
  }
  let interval = 1;
  vi.stubGlobal(
    'setInterval',
    vi.fn(() => interval++),
  );
  vi.stubGlobal('clearInterval', vi.fn());
  vi.stubGlobal('window', page);
  vi.stubGlobal('document', document);
  vi.stubGlobal('navigator', { mediaDevices: { getDisplayMedia } });
  vi.stubGlobal('MediaStreamTrackProcessor', Processor);
  const capture = await import('./capture');
  capture.startCapture(
    () => -100,
    () => null,
  );
  if (onScreen) showOnScreen(capture);
  const deliver = (port: EncoderPort, role: 'encoder' | 'video-out' = 'encoder') => {
    const event = new Event('message');
    Object.defineProperties(event, {
      source: { value: page },
      data: { value: { drashtiStreamPort: role } },
      ports: { value: [port] },
    });
    page.dispatchEvent(event);
  };
  const ended = (generation: number, frames: number) =>
    lines.includes(`[program] capture ${String(generation)} ended after ${String(frames)} frames`);
  disposeCapture = async () => {
    // Resolve platform requests before retiring them, then close only these generated readers.
    await expect
      .poll(() => tracks.filter((track) => track.processorStarted || track.stop.mock.calls.length > 0).length)
      .toBe(getDisplayMedia.mock.calls.length);
    capture.stopEncoder();
    capture.stopPreview();
    stopVideoOut(capture);
    for (const track of tracks) track.finishReader();
    await expect
      .poll(
        () => lines.filter((line) => /^\[program\] capture \d+ ended after \d+ frames$/u.test(line)).length,
      )
      .toBe(tracks.filter((track) => track.processorStarted).length);
  };
  return { capture, deliver, getDisplayMedia, body, ended };
}

describe('Program capture while its picture request is still pending', () => {
  it('shares one acquisition when encoder and video-out ports arrive before its track', async () => {
    const first = new GeneratedTrack(4, 2);
    const second = new GeneratedTrack(4, 2);
    const third = new GeneratedTrack(4, 2);
    const p = await platform([first, second, third]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const encoder = new EncoderPort(),
      out = new EncoderPort(),
      replacement = new EncoderPort();
    p.deliver(encoder);
    p.deliver(out, 'video-out');
    p.deliver(replacement);
    expect(p.getDisplayMedia, 'one platform request while its first track is pending').toHaveBeenCalledTimes(
      1,
    );
    await expect.poll(() => first.processorStarted).toBe(true);
    first.frame(61);
    await expect.poll(() => videoBytes(replacement)).toEqual([Array<number>(32).fill(61)]);
    await expect.poll(() => videoBytes(out)).toEqual([Array<number>(32).fill(61)]);
    expect(first.stop).not.toHaveBeenCalled();
  });

  it('stops an acquired track if the last consumer left before it arrived', async () => {
    const first = new GeneratedTrack(4, 2);
    const p = await platform([first]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    p.deliver(new EncoderPort());
    p.capture.stopEncoder();
    await expect.poll(() => first.stop.mock.calls.length).toBe(1);
    expect(first.processorStarted).toBe(false);
    expect(p.getDisplayMedia).toHaveBeenCalledTimes(1);
  });

  it('retires an old pending size and acquires the requested new size once', async () => {
    const first = new GeneratedTrack(4, 2),
      second = new GeneratedTrack(6, 4);
    const p = await platform([first, second]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const encoder = new EncoderPort();
    p.deliver(encoder);
    p.capture.setCaptureSize({ width: 6, height: 4 });
    await expect.poll(() => second.processorStarted).toBe(true);
    expect(first.stop).toHaveBeenCalledTimes(1);
    expect(first.processorStarted).toBe(false);
    expect(p.getDisplayMedia).toHaveBeenCalledTimes(2);
    expect(p.getDisplayMedia).toHaveBeenNthCalledWith(2, {
      video: { width: 6, height: 4, frameRate: 30 },
      audio: false,
    });
    second.frame(62);
    await expect.poll(() => videoBytes(encoder)).toEqual([Array<number>(96).fill(62)]);
  });
});

describe('Program capture after a reader ends', () => {
  it('asks for its picture again for a replacement encoder port and sends its new format and frame', async () => {
    const first = new GeneratedTrack(4, 2);
    const second = new GeneratedTrack(4, 2);
    const unexpected = new GeneratedTrack(4, 2);
    const p = await platform([first, second, unexpected]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const originalPort = new EncoderPort();
    p.deliver(originalPort);
    await expect.poll(() => first.processorStarted).toBe(true);
    first.frame(17);
    await expect.poll(() => videoBytes(originalPort)).toEqual([Array<number>(32).fill(17)]);

    first.endNaturally();
    await expect.poll(() => p.ended(1, 1)).toBe(true);
    const replacementPort = new EncoderPort();
    p.deliver(replacementPort);
    await expect.poll(() => p.getDisplayMedia.mock.calls.length).toBe(2);
    expect(p.getDisplayMedia).toHaveBeenNthCalledWith(2, {
      video: { width: 4, height: 2, frameRate: 30 },
      audio: false,
    });
    await expect.poll(() => second.processorStarted).toBe(true);
    second.frame(34);
    await expect.poll(() => videoBytes(replacementPort)).toEqual([Array<number>(32).fill(34)]);
    expect(replacementPort.messages[0]).toEqual({ kind: 'format', width: 4, height: 2, format: 'RGBA' });
    expect(originalPort.close).toHaveBeenCalledTimes(1);
    expect(p.body.dataset['capture']).toBe('on');
  });

  it('keeps the newer size, cached and following frames, and active marker when the previous reader finishes late', async () => {
    const first = new GeneratedTrack(4, 2);
    const second = new GeneratedTrack(6, 4);
    const unexpected = new GeneratedTrack(6, 4);
    const p = await platform([first, second, unexpected]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const originalPort = new EncoderPort();
    p.deliver(originalPort);
    await expect.poll(() => first.processorStarted).toBe(true);
    first.frame(51);
    await expect.poll(() => videoBytes(originalPort)).toHaveLength(1);
    p.capture.setCaptureSize({ width: 6, height: 4 });
    await expect.poll(() => second.processorStarted).toBe(true);
    second.frame(68);
    await expect.poll(() => videoBytes(originalPort)).toHaveLength(2);
    expect(first.stop).toHaveBeenCalledTimes(1);

    // The old processor finishes only after the new capture has a valid cached frame.
    first.finishReader();
    await expect.poll(() => p.ended(1, 1)).toBe(true);
    const replacementPort = new EncoderPort();
    p.deliver(replacementPort);
    await expect.poll(() => videoBytes(replacementPort)).toEqual([Array<number>(96).fill(68)]);
    expect(replacementPort.messages[0]).toEqual({ kind: 'format', width: 6, height: 4, format: 'RGBA' });
    expect(p.getDisplayMedia).toHaveBeenCalledTimes(2);
    expect(second.stop).not.toHaveBeenCalled();
    second.frame(85);
    await expect
      .poll(() => videoBytes(replacementPort))
      .toEqual([Array<number>(96).fill(68), Array<number>(96).fill(85)]);
    expect(p.getDisplayMedia).toHaveBeenCalledTimes(2);
    // Separate current-generation metadata check: the old reader must not announce the new capture as off.
    expect(p.body.dataset['capture']).toBe('on');
  });

  it('marks the capture off after its last encoder stops and that reader finishes', async () => {
    const first = new GeneratedTrack(4, 2);
    const unexpected = new GeneratedTrack(4, 2);
    const p = await platform([first, unexpected]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const port = new EncoderPort();
    p.deliver(port);
    await expect.poll(() => first.processorStarted).toBe(true);
    first.frame(102);
    await expect.poll(() => videoBytes(port)).toEqual([Array<number>(32).fill(102)]);

    // There is no preview port. Finish the stopped reader before checking its final state, as the old capture did.
    p.capture.stopEncoder();
    first.finishReader();
    await expect.poll(() => p.ended(1, 1)).toBe(true);
    expect(first.stop).toHaveBeenCalledTimes(1);
    expect(port.close).toHaveBeenCalledTimes(1);
    expect(p.getDisplayMedia).toHaveBeenCalledTimes(1);
    expect(p.body.dataset['capture']).toBe('off');
  });
});

describe('the stream starts from the first frame that shows the show (Session 58, h-black2)', () => {
  it('gives a new encoder none of the frames captured before the page’s show is on screen, then the first one after it', async () => {
    const track = new GeneratedTrack(4, 2);
    const unexpected = new GeneratedTrack(4, 2);
    const p = await platform([track, unexpected], { onScreen: false });
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const port = new EncoderPort();
    p.deliver(port);
    await expect.poll(() => track.processorStarted).toBe(true);
    // The page's own black as it comes up, then a frame or two before the show is on screen.
    track.frame(3);
    track.frame(4);
    await expect.poll(() => p.body.dataset['frames']).toBe('2');
    expect(videoBytes(port), 'nothing to the encoder before the show is on screen').toEqual([]);
    showOnScreen(p.capture);
    // Not the frame captured before (the newest, kept): the window paints, and the next frame goes.
    track.frame(90);
    await expect.poll(() => videoBytes(port)).toEqual([Array<number>(32).fill(90)]);
    track.frame(91);
    await expect
      .poll(() => videoBytes(port))
      .toEqual([Array<number>(32).fill(90), Array<number>(32).fill(91)]);
  });

  it('gives the encoder the page as it is 15 s after its port came when the show is still not on screen, a new port meanwhile not restarting the wait', async () => {
    const track = new GeneratedTrack(4, 2);
    const unexpected = new GeneratedTrack(4, 2);
    const p = await platform([track, unexpected], { onScreen: false });
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const real = globalThis.setTimeout;
    const waits: { run: () => void; ms: number }[] = [];
    vi.stubGlobal(
      'setTimeout',
      vi.fn((run: () => void, ms?: number) => {
        if (ms === 15_000) {
          waits.push({ run, ms });
          return waits.length;
        }
        return real(run, ms);
      }),
    );
    const first = new EncoderPort();
    p.deliver(first);
    await expect.poll(() => track.processorStarted).toBe(true);
    track.frame(3);
    track.frame(4);
    await expect.poll(() => p.body.dataset['frames']).toBe('2');
    // Main's picture watch gives the page a new port at 5 s: the wait goes on from the first port.
    const second = new EncoderPort();
    p.deliver(second);
    expect(waits.map((w) => w.ms)).toEqual([15_000]);
    expect(videoBytes(first)).toEqual([]);
    expect(videoBytes(second)).toEqual([]);
    // 15 s after the first port: the newest frame at once, and every frame from then.
    waits[0]?.run();
    await expect.poll(() => videoBytes(second)).toEqual([Array<number>(32).fill(4)]);
    track.frame(5);
    await expect
      .poll(() => videoBytes(second))
      .toEqual([Array<number>(32).fill(4), Array<number>(32).fill(5)]);
    expect(videoBytes(first)).toEqual([]);
  });

  it('gives an encoder that comes once the show is on screen the newest frame at once, as before', async () => {
    const track = new GeneratedTrack(4, 2);
    const unexpected = new GeneratedTrack(4, 2);
    const p = await platform([track, unexpected], { onScreen: false });
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const first = new EncoderPort();
    p.deliver(first);
    await expect.poll(() => track.processorStarted).toBe(true);
    showOnScreen(p.capture);
    track.frame(40);
    await expect.poll(() => videoBytes(first)).toEqual([Array<number>(32).fill(40)]);
    // A replacement port (Main's picture watch, or going live while recording): the picture as it stands, at once.
    const second = new EncoderPort();
    p.deliver(second);
    await expect.poll(() => videoBytes(second)).toEqual([Array<number>(32).fill(40)]);
  });
});

/** A frame whose clones' bytes are copied only once `gate` opens (a slow copy for video out); its own at once. */
class GatedFrame extends GeneratedFrame {
  constructor(
    width: number,
    height: number,
    private readonly value: number,
    private readonly gate: Promise<void>,
    private readonly gated = false,
  ) {
    super(width, height, value);
  }

  override clone(): VideoFrame {
    return new GatedFrame(this.codedWidth, this.codedHeight, this.value, this.gate, true).asVideoFrame();
  }

  override async copyTo(destination: ArrayBuffer): Promise<PlaneLayout[]> {
    if (this.gated) await this.gate;
    return super.copyTo(destination);
  }
}

describe('video out takes the same capture’s frames, never holding it (x30)', () => {
  it('gives video out’s port each frame raw, its format first, beside the encoder’s, which are as before', async () => {
    const track = new GeneratedTrack(4, 2);
    const unexpected = new GeneratedTrack(4, 2);
    const p = await platform([track, unexpected]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const encoder = new EncoderPort();
    const out = new EncoderPort();
    p.deliver(encoder);
    await expect.poll(() => track.processorStarted).toBe(true);
    // Video out's port comes to a capture already running (two at once would each ask for the picture).
    p.deliver(out, 'video-out');
    track.frame(21);
    track.frame(22);
    await expect
      .poll(() => videoBytes(out))
      .toEqual([Array<number>(32).fill(21), Array<number>(32).fill(22)]);
    expect(out.messages[0]).toEqual({ kind: 'format', width: 4, height: 2, format: 'RGBA' });
    expect(videoBytes(encoder)).toEqual([Array<number>(32).fill(21), Array<number>(32).fill(22)]);
    expect(encoder.messages[0]).toEqual({ kind: 'format', width: 4, height: 2, format: 'RGBA' });
    expect(p.getDisplayMedia).toHaveBeenCalledTimes(1);
  });

  it('lets go of a frame that comes while the one before is still on its way to video out; the encoder gets every one', async () => {
    const track = new GeneratedTrack(4, 2);
    const unexpected = new GeneratedTrack(4, 2);
    const p = await platform([track, unexpected]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const encoder = new EncoderPort();
    const out = new EncoderPort();
    p.deliver(encoder);
    await expect.poll(() => track.processorStarted).toBe(true);
    p.deliver(out, 'video-out');
    let open = (): void => undefined;
    const gate = new Promise<void>((resolve) => {
      open = resolve;
    });
    track.enqueue(new GatedFrame(4, 2, 31, gate).asVideoFrame());
    track.frame(32);
    track.frame(33);
    await expect.poll(() => videoBytes(encoder)).toHaveLength(3);
    expect(videoBytes(out)).toEqual([]);
    open();
    await expect.poll(() => videoBytes(out)).toEqual([Array<number>(32).fill(31)]);
    track.frame(34);
    await expect
      .poll(() => videoBytes(out))
      .toEqual([Array<number>(32).fill(31), Array<number>(32).fill(34)]);
    expect(videoBytes(encoder).map((b) => b[0])).toEqual([31, 32, 33, 34]);
  });

  it('starts the capture for video out alone, and stops it when video out stops and nothing else wants it', async () => {
    const track = new GeneratedTrack(4, 2);
    const unexpected = new GeneratedTrack(4, 2);
    const p = await platform([track, unexpected]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const out = new EncoderPort();
    p.deliver(out, 'video-out');
    await expect.poll(() => track.processorStarted).toBe(true);
    track.frame(41);
    await expect.poll(() => videoBytes(out)).toEqual([Array<number>(32).fill(41)]);
    stopVideoOut(p.capture);
    expect(out.close).toHaveBeenCalledTimes(1);
    expect(track.stop).toHaveBeenCalledTimes(1);
    track.finishReader();
    await expect.poll(() => p.ended(1, 1)).toBe(true);
    expect(p.body.dataset['capture']).toBe('off');
  });

  it('waits, as the encoder does, for the page’s show to be on screen, then takes the first frame after', async () => {
    const track = new GeneratedTrack(4, 2);
    const unexpected = new GeneratedTrack(4, 2);
    const p = await platform([track, unexpected], { onScreen: false });
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const out = new EncoderPort();
    p.deliver(out, 'video-out');
    await expect.poll(() => track.processorStarted).toBe(true);
    track.frame(3);
    await expect.poll(() => p.body.dataset['frames']).toBe('1');
    expect(videoBytes(out)).toEqual([]);
    showOnScreen(p.capture);
    track.frame(50);
    await expect.poll(() => videoBytes(out)).toEqual([Array<number>(32).fill(50)]);
  });
});
